  PanelText_UI_Events_Panel_Arachne_StageGroup_Text_C_Introduction_Content = {
    Text = "灯光亮起。掌声平息。观众们期待着。\n上台的时候到了，我亲爱的孩子们。去登台，去表演，去撕开你们的肺腑，出卖你们最深的隐秘。去用你们最惨烈的伤口，做成供人取悦的甜点。去贪婪地享受舞台上那道只为你点亮的光，直到帷幕将你与观众一同埋葬。\n这是你们命中注定的舞台，登上它吧！不要害怕，无需怯场。"
