  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Introduction_Content = {
    Text = "♪~~♫~~♪~~♫~~♪~~♫~~\n在雪山下，所有的向导都记得，所有的孩子都将它传唱。那是巍峨雪山意志的化身，那是慈悲的神女乌摩钵蒂。\n她的神力散落人间，她的宝物无从寻觅，它们近在咫尺，它们渺无踪迹。放弃一些什么吧，坚持一些什么吧。\n对神女的真身心有不诚者，将与死去的雪山一同，永远葬身在雪山。"
  },
  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Resonance_Content = {Text = "共鸣"},
