  },
  PanelText_UI_Events_Panel_Castor_StageGroup_Text_C_Introduction_Content = {
    Text = "飞鸟的一生，注定是自由的一生。你该看到它的破壳之时，它从死亡手中夺回生的自由。 你该看到它的学飞之时，它从安逸的温巢中夺回独自生存的自由。如今若将自由的钥匙丢入死亡的深渊，那么它必将毫不犹豫地一跃而下，在狭窄的生命与无限的自由中，选择直面死亡的暴风。"
  },
