  PanelText_UI_Events_Panel_Clementine_StageGroup_Text_C_Introduction_Content = {
    Text = "自那时起，她便不再落下一滴眼泪。\n独自一人游弋徘徊，徘徊在遍地异类的世界。\n一场盛大的计划即将开始，作为她谢幕的最后告别。\n她是最成功的心理医生，这是她最成功的一次治疗。"
