  PanelText_UI_Events_Panel_Daffodil_StageGroup_Text_C_Introduction_Content = {
    Text = "这座海滨的小镇上，拥有一条繁华的商业街。海上贸易令这里汇集了无数时新的百货，只要付出足够的雷欧坊，你总能收获满意的商品。\n只有街角一间小小的店铺除外，那是一家充满了神奇古董的小店，在烟斗吐出的烟雾中，戴着宽檐帽子的老板娘会向你缓缓露出一个微笑。\n“欢迎来到解忧小店，这里能满足您的一切需要，只要付出足够的报酬……”\n“当然，当然，价格公道，童叟无欺。”"
  },
