  PanelText_UI_Events_Panel_KathiguRa_StageGroup_Text_C_Introduction_Content = {
    Text = "她再次屹立于大地之上，烬灭一切的复仇便如约而至。\n\n那是永不停息的追猎，那是爆燃之主的炙火。\n\n她将行过每一个角落，猎杀所有与死神签订契约之徒。\n\n逃吧，逃吧，逃到更深的黑暗中去吧，逃到自以为不会被找到的地方去吧。\n\n尽管这毫无意义，因为祂终将踏过每一个世界。\n\n祂会猎尽所有，直至一切烬灭如灰。"
  },
