  PanelText_UI_Events_Panel_Mouchette_StageGroup_Text_C_Introduction_Content = {
    Text = "突然有一天，你发现自己变得不一样了。\n没有人发现这一点，因为你有着一样的行为举止，一样的盛世容颜。\n但你很清楚，那颗原本鲜红的心，已经被覆上一张雾气构成的假面。 \n「如果我能一直伪装下去，那是否我依然是此前的我？」\n可喜可贺，这个问题并没有在你的大脑里停留超过一秒，反正在揭开那张假面之前，没有人知道你真实的想法。\n「那就，先出发吧~」"
  },
