    Text = "她注视着世界尽头的那扇大门，毫不犹豫地跨出了脚步。\n咔哒，她拧开把手，迫不及待地望向门后。\n然而门后空无一物，她一脚踩空，坠入了虚无。\n她早该知道，礼物来得太过直接， 便总会有些高昂的代价。"
