  PanelText_UI_Events_Panel_Pickman_StageGroup_Text_C_Introduction_Content = {
    Text = "理智与崩溃之间，诡谲的绘卷徐徐展开。\n你唾弃的幻觉，绘就绮丽的色彩，\n你畏惧的失控，构成忠诚的形式。\n在这里，疯狂是艺术的本能，是世界的根源，\n是唯一不会撒谎的真实。"
  },
