    Text = "科学，无关紧要。\n伦理，无关紧要。\n道德，无关紧要。\n生命，死亡，希望，绝望……最终的最终，地下室的笔记本上，用两种笔迹留下同一个推演。\n祂们说：「看，爱是唯一的、永恒的主题。」"
